    make(3, "正方形邊長為 11 公分，其對角線長是多少？", {"A": "11 公分", "B": "11√2 公分", "C": "22 公分", "D": "121√2 公分"}, "B", "正方形對角線是兩股 11 的直角三角形斜邊，d=√(11²+11²)=11√2，選 B。", "把對角線看成斜邊，再提出平方因子。", ["兩股都為 11。", "列式 d²=11²+11²=242。", "提出 121：√242=√(121×2)。", "得到 d=11√2。", "所以選 B。"], "easy"),
    make(4, "正八邊形的每一個內角是多少？", {"A": "120°", "B": "135°", "C": "140°", "D": "150°"}, "B", "正八邊形內角和=(8-2)×180°=1080°，八角相等，每角=1080°÷8=135°，選 B。", "先算多邊形內角總和，再除以相等的角數。", ["確認邊數 n=8。", "內角和為 6×180°=1080°。", "正八邊形八個內角相等。", "計算 1080°÷8=135°。", "所以選 B。"], "medium"),
    make(5, "菱形的兩條對角線長 10 公分與 24 公分，面積是多少平方公分？", {"A": "60", "B": "120", "C": "240", "D": "340"}, "B", "菱形面積=兩對角線乘積的一半=(10×24)÷2=120 平方公分，選 B。", "看到菱形對角線面積公式，先相乘再取一半。", ["讀取兩對角線 10 與 24。", "套用面積=(d1×d2)÷2。", "計算 10×24=240。", "取一半得 120。", "所以選 B。"], "easy"),
    make(6, "箏形的兩條對角線長 14 公分與 18 公分，且互相垂直，面積是多少平方公分？", {"A": "63", "B": "126", "C": "252", "D": "324"}, "B", "兩對角線互相垂直時，箏形面積=(14×18)÷2=126 平方公分，選 B。", "使用對角線分割成四個直角三角形的面積總和公式。", ["確認兩對角線垂直。", "相交對角線可作為面積公式的兩個方向。", "計算乘積 14×18=252。", "除以 2 得 126。", "所以選 B。"], "medium"),
    make(7, "等腰梯形的一個底角為 62°，則同一底上的另一個底角是多少？", {"A": "31°", "B": "62°", "C": "118°", "D": "124°"}, "B", "等腰梯形同一底上的兩個底角相等，因此另一個底角也是 62°，選 B。", "先辨認『同一底』，使用等腰梯形底角相等，而非鄰補角互補。", ["確認梯形為等腰梯形。", "等腰梯形同一底的兩底角相等。", "已知其中一角為 62°。", "另一個同底角也為 62°。", "所以選 B。"], "easy"),
    make(8, "一個正三角形的周長為 36 公分，每一邊長是多少？", {"A": "9 公分", "B": "10 公分", "C": "12 公分", "D": "18 公分"}, "C", "正三角形三邊等長，邊長=36÷3=12 公分，選 C。", "正三角形周長由三個相等邊組成，直接平均分配。", ["確認三邊長相等。", "周長 36 是三邊總和。", "用 36÷3。", "得到每邊 12 公分。", "所以選 C。"], "easy"),
